const stage=document.querySelector('#helix-stage');
if(stage){let started=false;function start(){if(started)return;started=true;import('./dna-helix.js?v='+encodeURIComponent(stage.dataset.assetVersion||'quantex-2')).catch(()=>{stage.classList.remove('is-ready');stage.querySelector('.stage-controls').hidden=true;stage.dataset.renderer='static';stage.setAttribute('aria-label','DNA double helix illustration');});}if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){observer.disconnect();if('requestIdleCallback'in window)requestIdleCallback(start,{timeout:800});else setTimeout(start,0);}},{rootMargin:'200px'});observer.observe(stage);}else start();}
